import json, sys

raw = json.load(sys.stdin)
parsed = json.loads(raw['result'])
exps_dict = parsed['data']['experiments']

# Group by benchmark+method
groups = {}
for exp_id, exp in exps_dict.items():
    bench = exp.get('benchmark', 'unknown')
    method = exp.get('method', 'unknown')
    seed = exp.get('seed', '?')
    metrics = exp.get('metrics', {})
    if isinstance(metrics, str):
        metrics = json.loads(metrics)
    sr = metrics.get('success_rate', metrics.get('overall_success_rate', metrics.get('overall_sr', '?')))
    config = exp.get('config', {})
    if isinstance(config, str):
        config = json.loads(config)
    updated = str(exp.get('updated_at', '?'))[:10]
    notes = str(exp.get('notes', '') or '')[:60]

    key = f'{bench}|{method}'
    if key not in groups:
        groups[key] = []
    groups[key].append({
        'seed': seed, 'sr': sr, 'config': config, 
        'exp_id': exp_id, 'updated': updated, 'notes': notes
    })

for key in sorted(groups.keys()):
    bench, method = key.split('|', 1)
    entries = groups[key]
    entries.sort(key=lambda x: (str(x['seed']), x['updated']))
    print(f'\n=== {bench} | {method} ({len(entries)} exps) ===')
    for e in entries:
        config_str = ''
        if e['config'] and isinstance(e['config'], dict):
            for ck in ['norm_eps', 'epsilon', 'K', 'k', 'percentile', 'mode', 'norm']:
                if ck in e['config']:
                    config_str += f' {ck}={e[\"config\"][ck]}'
        print(f'  seed={e[\"seed\"]} SR={e[\"sr\"]}{config_str} | {e[\"exp_id\"]} | {e[\"updated\"]} | {e[\"notes\"]}')
" 2>&1
